import{_ as a,o as n,c as s,a2 as i}from"./chunks/framework.mRCPFc5l.js";const h=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1786947182000}'),t={name:"guide/introduction.md"};function r(o,e,l,p,d,c){return n(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>NeoFlux is a lightweight, cross-platform C++20 UI framework designed for embedded and mobile applications. It follows a two-layer architecture inspired by Flutter&#39;s widget model, separating business logic/layout from rendering.</p><h2 id="design-goals" tabindex="-1">Design Goals <a class="header-anchor" href="#design-goals" aria-label="Permalink to &quot;Design Goals&quot;">​</a></h2><ul><li><strong>Lightweight</strong>: Minimal dependencies, small binary footprint, suitable for resource-constrained devices.</li><li><strong>Cross-platform</strong>: Single codebase for desktop (Windows/Linux/macOS) and mobile (Android/iOS).</li><li><strong>Declarative widgets</strong>: Compose UIs from reusable widget classes. Override virtual functions to customize behavior.</li><li><strong>Flex layout</strong>: Powered by <a href="https://github.com/Tencent/taitank" target="_blank" rel="noreferrer">Taitank</a>, a high-performance flexbox layout engine from Tencent.</li><li><strong>Thread-safe</strong>: Application and render layers communicate via a lock-free SPSC ring queue.</li></ul><h2 id="two-layer-architecture" tabindex="-1">Two-Layer Architecture <a class="header-anchor" href="#two-layer-architecture" aria-label="Permalink to &quot;Two-Layer Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Application Layer                      │</span></span>
<span class="line"><span>│  - Business logic                       │</span></span>
<span class="line"><span>│  - Widget tree                          │</span></span>
<span class="line"><span>│  - Taitank flex layout                  │</span></span>
<span class="line"><span>│  - Event loop + coroutines              │</span></span>
<span class="line"><span>└───────────────┬─────────────────────────┘</span></span>
<span class="line"><span>                │  SPSC RingQueue (RenderCommand)</span></span>
<span class="line"><span>                ▼</span></span>
<span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│  Render Layer                           │</span></span>
<span class="line"><span>│  - Consumes render commands             │</span></span>
<span class="line"><span>│  - Mobile: tgfx direct rendering        │</span></span>
<span class="line"><span>│  - Desktop: GLFW bridge + OpenGL        │</span></span>
<span class="line"><span>└─────────────────────────────────────────┘</span></span></code></pre></div><p>The application layer builds the widget tree, runs Taitank layout, and submits render commands. The render layer consumes those commands on a dedicated thread and draws to the screen. This separation keeps the UI responsive even during heavy rendering.</p><h2 id="license" tabindex="-1">License <a class="header-anchor" href="#license" aria-label="Permalink to &quot;License&quot;">​</a></h2><p>NeoFlux is released under the <strong>GPL-3.0</strong> license. See the <code>LICENSE</code> file for details.</p>`,9)])])}const g=a(t,[["render",r]]);export{h as __pageData,g as default};
